  doctor(options: {
    plugin?: string;
    verbose?: boolean;
    root?: string;
  }): Promise<unknown>;
  relink(options: {
    check?: boolean;
    auto?: boolean;
    root?: string;
  }): Promise<unknown>;
  buildBins(options: {
    root?: string;
  }): Promise<unknown>;
  tools(options: {
    fetch?: boolean;
    root?: string;
  }): Promise<unknown>;
};

declare module 'claude-code' {
  interface EngineInterface {
    setup: Setup;
  }
}

